python3 -c "
import json

with open('/app/resources/treasury_bulletin_1943_01.json', 'r') as f:
    data = json.load(f)

elements = data['document']['elements']
for i, el in enumerate(elements):
    if el.get('type') == 'table':
        content = el.get('content', '')
        if '1941-December' in content:
            print(f'Found table {i} with 1941-December')
            # Print some of the content to understand structure
            if 'Treasury bonds' in content and 'Certificates of indebtedness' in content:
                print('This has Treasury bonds and Certificates of indebtedness!')
                # Find the section with month headers
                lines = content.split('<tr>')
                for j, line in enumerate(lines):
                    if 'Jan.</th>' in line or 'Dec.</th>' in line:
                        print(f'Header row {j}: {line[:300]}')
                break
"
